54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Maximum number of owners a single city may contain; creating an owner in a city that
64	     *  already has this many owners is rejected with 409 Conflict. */
65	    private static final int MAX_OWNERS_PER_CITY = 50;
66	
67	    /** Maximum number of owners that may be created on a single day (by registration date); creating
68	     *  an owner once this many owners already carry today's registration date is rejected with
69	     *  429 Too Many Requests. */
70	    private static final int MAX_OWNERS_PER_DAY = 100;
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    private final TelephoneNormalizer telephoneNormalizer;
81	
82	    private final HouseholdNormalizer householdNormalizer;
83	
84	    private final AddressNormalizer addressNormalizer;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper,
90	                                 TelephoneNormalizer telephoneNormalizer,
91	                                 HouseholdNormalizer householdNormalizer,
92	                                 AddressNormalizer addressNormalizer) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	        this.telephoneNormalizer = telephoneNormalizer;
98	        this.householdNormalizer = householdNormalizer;
99	        this.addressNormalizer = addressNormalizer;
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
105	        Collection<Owner> owners;
106	        if (lastName != null) {
107	            owners = this.clinicService.findOwnerByLastName(lastName);
108	        } else {
109	            owners = this.clinicService.findAllOwners();
110	        }
111	        if (owners.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        normalizeOwnerFields(owner);
133	        // Enforce the pre-persistence policies that can reject the new owner outright.
134	        rejectDisallowedOwnerCreation(owner);
135	        // Identify any existing owners who share a household (same last name and address,
136	        // compared case-insensitively with collapsed whitespace) with the owner being created.
137	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
138	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
139	        // Reject creating an owner who shares a household with an existing owner, unless the
140	        // request explicitly opts in with 'sharesHousehold' true.
141	        if (!sharesHousehold && !householdMembers.isEmpty()) {
142	            throw new DuplicateHouseholdException(
143	                "An owner with the same last name and address already exists");
144	        }
145	        // When opting in and joining an existing household, assign the new owner and every
146	        // existing member the same stable household identifier derived from the last name and
147	        // address, so all owners of the household share one 'householdId'.
148	        if (sharesHousehold && !householdMembers.isEmpty()) {
149	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
150	            owner.setHouseholdId(householdId);
151	            for (Owner member : householdMembers) {
152	                if (!householdId.equals(member.getHouseholdId())) {
153	                    member.setHouseholdId(householdId);
154	                    this.clinicService.saveOwner(member);
155	                }
156	            }
157	        }
158	        // Record how many existing owners already share this owner's first and last name
159	        // (compared case-insensitively) before this create, fixed at creation time.
160	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
161	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' from the city, last name and a
162	        // per-city sequence equal to one more than the owners already in that city, fixed at
163	        // creation time.
164	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
165	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
166	        // of the registration date's year (e.g. 'LON-SMI-0007-M26'), fixed at creation time.
167	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
168	        this.clinicService.saveOwner(owner);
169	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
170	        headers.setLocation(UriComponentsBuilder.newInstance()
171	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
172	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
173	    }
174	
175	    /**
176	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
177	     * outright, in order, before any derived fields are assigned or the owner is saved. An owner
178	     * in a city that already contains {@link #MAX_OWNERS_PER_CITY} owners is rejected with 409
179	     * ({@link CityCapacityExceededException}), and an owner whose normalized telephone is already
180	     * used by another owner is rejected with 409 ({@link DuplicateTelephoneException}). Grouping the
181	     * independent create-time rejection rules here keeps {@link #addOwner} focused on the household,
182	     * derived-field and persistence steps. The household rule stays in {@link #addOwner} itself
183	     * because it shares the matched-member lookup with the shared household-id assignment.
184	     *
185	     * @param owner the newly mapped and normalized owner being created
186	     */
187	    private void rejectDisallowedOwnerCreation(Owner owner) {
188	        // Reject creating an owner once 100 or more owners already carry this owner's adjusted
189	        // business-day registration date.
190	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
191	            throw new DailyOwnerLimitExceededException(
192	                "The maximum number of owners that may be created today has already been reached");
193	        }
194	        // Reject creating an owner when the owner's city already contains 50 or more owners.
195	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
196	            throw new CityCapacityExceededException(
197	                "The city " + owner.getCity() + " already contains the maximum number of owners");
198	        }
199	        // Reject creating an owner whose normalized telephone is already used by another owner.
200	        String normalizedTelephone = owner.getTelephone();
201	        if (isTelephoneInUse(normalizedTelephone)) {
202	            throw new DuplicateTelephoneException(
203	                "An owner with telephone " + normalizedTelephone + " already exists");
204	        }
205	    }
206	
207	    /**
208	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
209	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
210	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
211	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
212	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
213	     * server's current date. Canonicalising the address here, before the household checks read it,
214	     * ensures duplicate detection and the shared household id both compare the normalized form.
215	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
216	     * duplicate, household and customer-code rules.
217	     *
218	     * @param owner the newly mapped owner to canonicalize
219	     */
220	    private void normalizeOwnerFields(Owner owner) {
221	        // Normalize the address on create so it is stored and returned in canonical form and every
222	        // later comparison (household duplicate detection and the shared household id) uses it.
223	        // A value that is blank after normalization is rejected with 400.
224	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
225	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
226	        // A value that cannot form a valid E.164 number is rejected with 400.
227	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
228	        // Store the (already syntactically validated) email lower-cased so it is persisted and
229	        // returned in canonical form. A missing email is left untouched.
230	        owner.setEmail(normalizeEmail(owner.getEmail()));
231	        // Default the registration date to the server's current date when the client did not
232	        // supply one, then roll the effective date forward to a business day so a Saturday or
233	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
234	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
235	        // date-derived field (such as the membership number's year segment) and the per-day
236	        // create-limit are computed from.
237	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
238	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
239	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
240	    }
241	
242	    /**
243	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
244	     * following Monday, while a weekday is returned unchanged. Applied to the effective
245	     * registration date (whether supplied in the request or defaulted to the server date) so the
246	     * persisted registration date, every value derived from it and the per-day create-limit all
247	     * use the adjusted business day.
248	     *
249	     * @param date the effective registration date
250	     * @return the same date if it is a weekday, otherwise the following Monday
251	     */
252	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
253	        java.time.LocalDate adjusted = date;
254	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
255	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
256	            adjusted = adjusted.plusDays(1);
257	        }
258	        return adjusted;
259	    }
260	
261	    /**
262	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
263	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
264	     * syntactically valid address (rejecting anything else with 400).
265	     *
266	     * @param email the email value (may be {@code null})
267	     * @return the lower-cased email, or {@code null} if the input was {@code null}
268	     */
269	    private String normalizeEmail(String email) {
270	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
271	    }
272	
273	    /**
274	     * Builds the customer code '<CITY3>-<LAST3>-<NNNN>' for a newly created owner, where CITY3 is
275	     * the upper-cased first three letters of the city, LAST3 is the upper-cased first three letters
276	     * of the last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than
277	     * the owners already in that city (e.g. 'LON-SMI-0007').
278	     *
279	     * @param city     the owner's city
280	     * @param lastName the owner's last name
281	     * @return the formatted customer code
282	     */
283	    private String nextCustomerCode(String city, String lastName) {
284	        String cityPrefix = city.substring(0, Math.min(3, city.length()))
285	            .toUpperCase(java.util.Locale.ROOT);
286	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length()))
287	            .toUpperCase(java.util.Locale.ROOT);
288	        int sequence = countOwnersInCity(city) + 1;
289	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
290	    }
291	
292	    /**
293	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
294	     * fix the per-city sequence of an owner's customer code at creation time.
295	     *
296	     * @param city the city of the owner being created
297	     * @return the number of existing owners in a matching city
298	     */
299	    private int countOwnersInCity(String city) {
300	        return (int) this.clinicService.findAllOwners().stream()
301	            .filter(existing -> existing.getCity() != null
302	                && existing.getCity().equalsIgnoreCase(city))
303	            .count();
304	    }
305	
306	    /**
307	     * Counts the existing owners whose registration date is the given adjusted business day. Used
308	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
309	     * owners already carry that business day as their registration date.
310	     *
311	     * @param date the adjusted business-day registration date to match
312	     * @return the number of existing owners registered on that date
313	     */
314	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
315	        return (int) this.clinicService.findAllOwners().stream()
316	            .filter(existing -> date.equals(existing.getRegistrationDate()))
317	            .count();
318	    }
319	
320	    /**
321	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
322	     * the last two digits of the registration date's year (e.g. 'LON-SMI-0007-M26').
323	     *
324	     * @param customerCode     the owner's customer code
325	     * @param registrationDate the owner's registration date
326	     * @return the formatted membership number
327	     */
328	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
329	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
330	    }
331	
332	    /**
333	     * Determines whether the given normalized telephone is already used by an existing owner.
334	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
335	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
336	     * as the same number.
337	     *
338	     * @param normalizedTelephone the normalized (E.164) telephone to look for
339	     * @return {@code true} if another owner already uses this telephone
340	     */
341	    private boolean isTelephoneInUse(String normalizedTelephone) {
342	        if (normalizedTelephone == null) {
343	            return false;
344	        }
345	        return this.clinicService.findAllOwners().stream()
346	            .map(Owner::getTelephone)
347	            .map(telephoneNormalizer::normalize)
348	            .anyMatch(normalizedTelephone::equals);
349	    }
350	
351	    /**
352	     * Returns the existing owners who share the given household, i.e. have the same last name and
353	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
354	     * differing only in letter case or in incidental whitespace are treated as the same household.
355	     *
356	     * @param lastName the last name of the owner being created
357	     * @param address  the address of the owner being created
358	     * @return the existing owners with a matching last name and address (possibly empty)
359	     */
360	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
361	        String householdKey = householdNormalizer.householdKey(lastName, address);
362	        return this.clinicService.findAllOwners().stream()
363	            .filter(existing -> householdNormalizer
364	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
365	            .toList();
366	    }
367	
368	    /**
369	     * Counts the existing owners who share the given first and last name, compared
370	     * case-insensitively. Used to fix an owner's namesake count at creation time.
371	     *
372	     * @param firstName the first name of the owner being created
373	     * @param lastName  the last name of the owner being created
374	     * @return the number of existing owners with a matching first and last name
375	     */
376	    private int countNamesakes(String firstName, String lastName) {
377	        return (int) this.clinicService.findAllOwners().stream()
378	            .filter(existing -> existing.getFirstName() != null
379	                && existing.getFirstName().equalsIgnoreCase(firstName)
380	                && existing.getLastName() != null
381	                && existing.getLastName().equalsIgnoreCase(lastName))
382	            .count();
383	    }
384	
385	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
386	    @Override
387	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
388	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
389	        if (currentOwner == null) {
390	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
391	        }
392	        currentOwner.setAddress(ownerFieldsDto.getAddress());
393	        currentOwner.setCity(ownerFieldsDto.getCity());
394	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
395	        currentOwner.setLastName(ownerFieldsDto.getLastName());
396	        // Normalize the telephone to canonical E.164 form so it is stored and returned
397	        // consistently with create; an unformattable value is rejected with 400.
398	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
399	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
400	        this.clinicService.saveOwner(currentOwner);
401	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
402	    }
403	
404	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
405	    @Transactional
406	    @Override
407	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
408	        Owner owner = this.clinicService.findOwnerById(ownerId);
409	        if (owner == null) {
410	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
411	        }
412	        this.clinicService.deleteOwner(owner);
413	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
414	    }
415	
416	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
417	    @Override
418	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
419	        Owner owner = this.clinicService.findOwnerById(ownerId);
420	        if (owner == null) {
421	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
422	        }
423	        HttpHeaders headers = new HttpHeaders();
424	        Pet pet = petMapper.toPet(petFieldsDto);
425	        owner.setId(ownerId);
426	        pet.setOwner(owner);
427	        pet.getType().setName(null);
428	        this.clinicService.savePet(pet);
429	        PetDto petDto = petMapper.toPetDto(pet);
430	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
431	            .buildAndExpand(pet.getId()).toUri());
432	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
433	    }
434	
435	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
436	    @Override
437	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
438	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
439	        if (currentOwner != null) {
440	            Pet currentPet = this.clinicService.findPetById(petId);
441	            if (currentPet != null) {
442	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
443	                currentPet.setName(petFieldsDto.getName());
444	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
445	                this.clinicService.savePet(currentPet);
446	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
447	            }
448	        }
449	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
450	    }
451	
452	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
453	    @Override
454	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
455	        HttpHeaders headers = new HttpHeaders();
456	        Visit visit = visitMapper.toVisit(visitFieldsDto);
457	        Pet pet = new Pet();
458	        pet.setId(petId);
459	        visit.setPet(pet);
460	        this.clinicService.saveVisit(visit);
461	        VisitDto visitDto = visitMapper.toVisitDto(visit);
462	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
463	            .buildAndExpand(visit.getId()).toUri());
464	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
465	    }
466	
467	
468	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
469	    @Override
470	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
471	        Owner owner = this.clinicService.findOwnerById(ownerId);
472	        if (owner != null) {
473	            Pet pet = owner.getPet(petId);
474	            if (pet != null) {
475	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
476	            }
477	        }
478	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
479	    }
480	}
