17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	import org.springframework.stereotype.Component;
25	
26	/**
27	 * Produces the canonical key identifying the household an owner belongs to.
28	 * <p>
29	 * Centralising this here keeps the REST controllers thin: they delegate to
30	 * {@link #householdKey(String, String)} both when deciding whether a new owner shares a
31	 * household with an existing one and (in future) when deriving the shared household
32	 * identifier, so the two always agree on what "the same household" means.
33	 * <p>
34	 * Two owners belong to the same household when they have the same last name and the same
35	 * address. Both fields are compared case-insensitively after trimming and collapsing runs
36	 * of whitespace to a single space, so values that differ only in letter case or in
37	 * incidental spacing map to the same key. The normalized fields are joined with a newline,
38	 * which the normalization can never itself produce, so the key uniquely determines the
39	 * (last name, address) pair it was built from.
40	 */
41	@Component
42	public class HouseholdNormalizer {
43	
44	    /**
45	     * Builds the canonical household key for the given last name and address. Owners whose
46	     * last name and address normalize identically share a key and therefore a household.
47	     *
48	     * @param lastName the owner's last name (may be {@code null})
49	     * @param address  the owner's address (may be {@code null})
50	     * @return the canonical household key
51	     */
52	    public String householdKey(String lastName, String address) {
53	        return normalizeField(lastName) + '\n' + normalizeField(address);
54	    }
55	
56	    /**
57	     * Derives the stable shared identifier for the household with the given last name and
58	     * address. The identifier is a pure function of the canonical {@link #householdKey key},
59	     * so every owner in the same household derives the identical value and it never changes
60	     * between calls (a "stable shared identifier"). It is formatted 'HH-' followed by the
61	     * first 12 upper-case hex characters of the SHA-256 of the household key.
62	     *
63	     * @param lastName the owner's last name (may be {@code null})
64	     * @param address  the owner's address (may be {@code null})
65	     * @return the stable household identifier
66	     */
67	    public String householdId(String lastName, String address) {
68	        return "HH-" + sha256Hex(householdKey(lastName, address)).substring(0, 12).toUpperCase(Locale.ROOT);
69	    }
70	
71	    /**
72	     * Computes the lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
73	     *
74	     * @param value the value to hash
75	     * @return the hex-encoded digest
76	     */
77	    private String sha256Hex(String value) {
78	        try {
79	            byte[] digest = MessageDigest.getInstance("SHA-256")
80	                .digest(value.getBytes(StandardCharsets.UTF_8));
81	            StringBuilder sb = new StringBuilder(digest.length * 2);
82	            for (byte b : digest) {
83	                sb.append(String.format("%02x", b));
84	            }
85	            return sb.toString();
86	        }
87	        catch (NoSuchAlgorithmException e) {
88	            throw new IllegalStateException("SHA-256 not available", e);
89	        }
90	    }
91	
92	    /**
93	     * Normalizes a single household field by trimming, collapsing internal runs of
94	     * whitespace to a single space and lower-casing, so comparisons ignore case and
95	     * incidental whitespace differences.
96	     *
97	     * @param value the value to normalize (may be {@code null})
98	     * @return the normalized value, or the empty string if the input was {@code null}
99	     */
100	    private String normalizeField(String value) {
101	        if (value == null) {
102	            return "";
103	        }
104	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
105	    }
106	}
