214	    /**
215	     * Handles {@link InvalidTelephoneException}, raised when a supplied telephone value cannot be
216	     * normalized to a valid E.164 number, returning a 400 Bad Request status.
217	     *
218	     * @param e The {@link InvalidTelephoneException} to be handled
219	     * @param request {@link HttpServletRequest} object referring to the current request.
220	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
221	     */
222	    @ExceptionHandler(InvalidTelephoneException.class)
223	    @ResponseBody
224	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
225	        logger.warn("Invalid telephone at {} {}: {}",
