231	        return ResponseEntity.status(status).body(detail);
232	    }
233	
234	    /**
235	     * Handles {@link InvalidAddressException}, raised when a supplied address value is blank after
236	     * normalization (and so carries no address), returning a 400 Bad Request status.
237	     *
238	     * @param e The {@link InvalidAddressException} to be handled
239	     * @param request {@link HttpServletRequest} object referring to the current request.
240	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
241	     */
242	    @ExceptionHandler(InvalidAddressException.class)
243	    @ResponseBody
244	    public ResponseEntity<ProblemDetail> handleInvalidAddressException(InvalidAddressException e, HttpServletRequest request) {
245	        logger.warn("Invalid address at {} {}: {}",
246	            request.getMethod(),
247	            request.getRequestURI(),
248	            e.getMessage());
249	        HttpStatus status = HttpStatus.BAD_REQUEST;
250	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_ADDRESS);
251	        return ResponseEntity.status(status).body(detail);
252	    }
253	
254	    /**
255	     * Handles exception thrown by Bean Validation on controller methods parameters
256	     *
257	     * @param e The {@link MethodArgumentNotValidException} to be handled
258	     * @param request {@link HttpServletRequest} object referring to the current request.
259	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
260	     */
261	    @ExceptionHandler(MethodArgumentNotValidException.class)
262	    @ResponseBody
263	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
264	        HttpStatus status = HttpStatus.BAD_REQUEST;
265	        BindingErrorsResponse errors = new BindingErrorsResponse();
266	        BindingResult bindingResult = e.getBindingResult();
267	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
268	        if (bindingResult.hasErrors()) {
269	            errors.addAllErrors(bindingResult);
270	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
271	                .map(fieldError -> {
272	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
273	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
274	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
275	                        fieldError.getField(),
276	                        defaultMessage,
277	                        rejectedValue);
278	                    return new ValidationMessageDto(message)
279	                        .putAdditionalProperty("field", fieldError.getField())
280	                        .putAdditionalProperty("rejectedValue", rejectedValue)
281	                        .putAdditionalProperty("defaultMessage", defaultMessage);
282	                })
283	                .toList();
284	            logger.debug("Validation error at {} {}: {}",
285	                request.getMethod(),
286	                request.getRequestURI(),
287	                bindingResult.getFieldErrors());
288	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
289	            detail.setProperty("errors", rejectedFieldNames(bindingResult));
290	            return ResponseEntity.status(status).body(detail);
291	        }
292	        return ResponseEntity.status(status).body(detail);
293	    }
294	
295	    /**
296	     * Collects the distinct names of the fields that failed validation, in the order they were
297	     * reported, so responses can list the offending fields (e.g. those that are missing or blank).
298	     *
299	     * @param bindingResult the {@link BindingResult} carrying the validation field errors
300	     * @return the distinct rejected field names
301	     */
302	    private List<String> rejectedFieldNames(BindingResult bindingResult) {
303	        return bindingResult.getFieldErrors().stream()
304	            .map(FieldError::getField)
305	            .distinct()
306	            .toList();
307	    }
